import { writeFile } from 'node:fs/promises'
import { pathToFileURL } from 'node:url'
import { join } from 'node:path'
import { WorkspaceId } from '@deepseek-ai/dsh-workspace'
import { mountTeamMemberHost, provideQuietTokenMeter } from '../../../packages/agent-team/tests/helpers/team-host-fixture.ts'

const root = process.cwd()
const cleanups: Array<() => Promise<void>> = []
const host = await mountTeamMemberHost({
  cleanups, prepare: provideQuietTokenMeter,
  presetPlugins: [
    { id: 'member-context', name: '@contexera/dsh-agent-team/member-context' },
    { id: 'team-tools', name: pathToFileURL(join(root, 'packages/agent-team/tests/helpers/team-tools-fixture.mjs')).href },
  ],
  workingDirectory: 'stub',
})
const team = host.ctx.agentTeam as any
const workspaceId = WorkspaceId('workspace:fixture')
try {
  const project = await team.createProject({ requestId: 'review:project', workspaceId, name: 'review', description: 'Queue ordering review' })
  const members = []
  for (let i = 0; i < 8; i += 1) {
    const result = await team.addMember({ requestId: `review:add:${i}`, workspaceId, handle: `review-${i}`, description: 'Queue review', presetId: 'team-member', projectRefs: [project.project.projectRef] })
    members.push(result.status.member)
  }
  await team.notificationEffectTail
  const notifications: Array<{ memberId: string; sequence: number }> = []
  const affected: Array<{ sequence: number; count: number }> = []
  const originalAffected = team.ledger.affectedMembersOf.bind(team.ledger)
  team.ledger.affectedMembersOf = (operation: any) => {
    const result = originalAffected(operation)
    affected.push({ sequence: operation.sequence, count: result.length })
    return result
  }
  // Observe Host dispatch order only, keeping model scheduling out of this probe.
  team.notifyMember = (agent: any, cause: any) => {
    if (cause.kind === 'commit') notifications.push({ memberId: team.memberForAgent(agent)?.memberId, sequence: cause.receipt.sequence })
  }
  const first = await team.startThread({ kind: 'discussion', requestId: 'review:large', workspaceId, projectRef: project.project.projectRef,
    body: `${members.map(member => `@${member.handle}`).join(' ')} first` })
  const second = await team.startThread({ kind: 'discussion', requestId: 'review:small', workspaceId, projectRef: project.project.projectRef,
    body: `@${members[0].handle} second` })
  const beforeDrain = [...notifications]
  await team.notificationEffectTail
  const memberOrder = notifications.filter(row => row.memberId === members[0].memberId).map(row => row.sequence)
  const report = { first: first.receipt.sequence, second: second.receipt.sequence, affected, beforeDrain, notifications, memberOrder,
    ordered: memberOrder.every((value, index) => index === 0 || value >= memberOrder[index - 1]!) }
  await writeFile(join(import.meta.dirname, 'queue-order-result.json'), JSON.stringify(report, null, 2) + '\n')
  console.log(JSON.stringify(report, null, 2))
} finally {
  await Promise.all(cleanups.splice(0).map(cleanup => cleanup()))
}

