import assert from 'node:assert/strict'
import { spawnSync } from 'node:child_process'
import { mkdtemp, writeFile } from 'node:fs/promises'
import { join } from 'node:path'
import { sqliteHarness, addLedgerMember, agentTeamHumanActor, alpha, requestId } from '../../../packages/agent-team/tests/helpers/host-harness.ts'

const directory = await mkdtemp(join(import.meta.dirname, 'usage-fixture-'))
const database = join(directory, 'ledger.sqlite')
const test = await sqliteHarness(database)
let expected: unknown
try {
  const ledger = test.ctx.agentTeam['ledger']!
  const { member } = await addLedgerMember(ledger, undefined)
  await ledger.suspendMember({ requestId: requestId('review:suspend'), actor: agentTeamHumanActor(), workspaceId: alpha, memberId: member.memberId })
  await ledger.resumeMember({ requestId: requestId('review:resume'), actor: agentTeamHumanActor(), workspaceId: alpha, memberId: member.memberId })
  assert.equal(ledger.getMember(member.memberId)?.state, 'enabled')
  expected = { memberState: ledger.getMember(member.memberId)?.state, enabled: 1, suspended: 0 }
} finally {
  await test.fiber.dispose()
  await test.facility.closeAll()
  await test.backend.close()
}
const result = spawnSync(process.execPath, ['--import', 'tsx', 'scripts/team-performance/team-live-usage.ts', database, '--json'], { encoding: 'utf8' })
assert.equal(result.status, 0, result.stderr)
const actual = JSON.parse(result.stdout)
const report = { expected, actual: actual.members, operations: actual.operationKinds }
await writeFile(join(import.meta.dirname, 'usage-state-result.json'), JSON.stringify(report, null, 2) + '\n')
console.log(JSON.stringify(report, null, 2))

