import { mkdtemp } from 'node:fs/promises'
import { tmpdir } from 'node:os'
import { join } from 'node:path'
import { pathToFileURL } from 'node:url'
const target = process.argv[2]!
const { sqliteHarness, ledgerAtBoot, addLedgerMember, makeOwner, alpha, agentTeamHumanActor, requestId } = await import(pathToFileURL(join(target, 'packages/agent-team/tests/helpers/host-harness.ts')).href)
let path = process.argv[3]
if (path === undefined) {
  path = join(await mkdtemp(join(tmpdir(), 'team-replay-control-')), 'ledger.sqlite')
  const host = await sqliteHarness(path)
  const ledger = ledgerAtBoot(host)
  const member = await addLedgerMember(ledger, undefined, 'member:control', 'Control', 'control')
  const project = (await ledger.createProject({ requestId: requestId('control-project'), actor: agentTeamHumanActor(), workspaceId: alpha, name: 'Control', description: '', memberIds: [member.member.memberId] })).value.project
  await makeOwner(ledger, project.projectRef, member.member.memberId)
  for (let i=0;i<100;i++) {
    const started = (await ledger.startThread({ kind:'discussion',requestId:requestId(`control-thread-${i}`),actor:agentTeamHumanActor(),workspaceId:alpha,projectRef:project.projectRef,body:'Control Thread' })).value
    await ledger.changeAttention({ requestId:requestId(`control-follow-${i}`),actor:member.actor,workspaceId:alpha,threadRef:started.thread.threadRef,action:'follow' })
    await ledger.reply({ requestId:requestId(`control-reply-${i}`),actor:agentTeamHumanActor(),workspaceId:alpha,threadRef:started.thread.threadRef,baseRevision:started.thread.revision,body:'Control reply' })
  }
  await host.fiber.dispose(); await host.facility.closeAll(); await host.backend.close()
  console.log(JSON.stringify({path}))
} else {
  const samples=[]
  for(let i=0;i<24;i++) {
    const start=performance.now()
    const host=await sqliteHarness(path)
    const boot=performance.now()
    const ledger=ledgerAtBoot(host)
    const replay=performance.now()
    ledger.validate()
    const validate=performance.now()
    if(i>=3)samples.push({boot:boot-start,replay:replay-boot,validate:validate-replay,total:validate-start,operations:ledger.status().operationCount})
    await host.fiber.dispose(); await host.facility.closeAll(); await host.backend.close()
  }
  console.log(JSON.stringify({samples}))
}

